--
-- Table structure for table `sm_add_incomes`
--

DROP TABLE IF EXISTS `sm_add_incomes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sm_add_incomes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date` date DEFAULT NULL,
  `amount` float DEFAULT NULL,
  `file` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `item_sell_id` int DEFAULT NULL,
  `fees_collection_id` int DEFAULT NULL,
  `inventory_id` int DEFAULT NULL,
  `active_status` tinyint NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `income_head_id` int unsigned DEFAULT NULL,
  `account_id` int unsigned DEFAULT NULL,
  `payment_method_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT '1',
  `updated_by` int unsigned DEFAULT '1',
  `school_id` int unsigned DEFAULT '1',
  `academic_id` int unsigned DEFAULT NULL,
  `installment_payment_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sm_add_incomes_account_id_foreign` (`account_id`),
