--
-- Table structure for table `sm_currencies`
--

DROP TABLE IF EXISTS `sm_currencies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sm_currencies` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `symbol` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `currency_type` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT '2',
  `currency_position` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT '2',
  `space` tinyint(1) DEFAULT '1',
  `decimal_digit` int DEFAULT NULL,
  `decimal_separator` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `thousand_separator` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `school_id` int unsigned DEFAULT '1',
  `academic_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sm_currencies_school_id_foreign` (`school_id`),
  CONSTRAINT `sm_currencies_school_id_foreign` FOREIGN KEY (`school_id`) REFERENCES `sm_schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

